import sys
from collections import defaultdict, deque

def captainAmerica(N, M, V):
    graph = defaultdict(list)
    in_degree = [0] * (N + 1)

    for u, v in V:
        graph[u].append(v)
        in_degree[v] += 1

    queue = deque()
    for i in range(1, N + 1):
        if in_degree[i] == 0:
            queue.append(i)

    while queue:
        node = queue.popleft()
        for neighbor in graph[node]:
            in_degree[neighbor] -= 1
            if in_degree[neighbor] == 0:
                queue.append(neighbor)

    return sum(1 for x in in_degree[1:] if x == 0)

def main():
    import sys
    input = sys.stdin.read().split()
    index = 0
    N = int(input[index])
    M = int(input[index + 1])
    index += 2
    V = []
    for _ in range(M):
        u = int(input[index])
        v = int(input[index + 1])
        V.append([u, v])
        index += 2
    result = captainAmerica(N, M, V)
    print(result)

if __name__ == "__main__":
    main()
